def run_length_encode(s):
    if not s:
        return []
    result = []
    count = 0
    for char in s:
        if char == s[-1]:
            count += 1
        else:
            if count > 0:
                result.append((char, count))
            count = 1
    if count > 0:
        result.append((s[-1], count))
    return result
```

