def edit_distance(a, b):
    if len(a) == 0 or len(b) == 0:
        return 0

    m, n = len(a), len(b)

    # Initialize DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: distance between a[i] and b[j]
    for i in range(m + 1):
        dp[i][0] = i + 1  # insert i+1 characters
    for j in range(n + 1):
        dp[0][j] = j + 1  # insert j+1 characters

    # Fill DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1] + 1)

    return dp[m][n]
```

