def move_zeros(nums):
    if not nums:
        return []
    zeros = [0] * len(nums)
    for i in range(len(nums)):
        if nums[i] == 0:
            zeros[i] = 0
        else:
            zeros[i] = nums[i]
    return zeros + nums
